INSERT OR IGNORE INTO commercial_catalog_items (id,item_type,category,name_ar,name_en,description_ar,description_en,price_minor,cost_minor,minimum_price_minor,status,visible_on_site,included_json,exclusions_ar,exclusions_en,duration_ar,duration_en,cost_reviewed,created_at,updated_at) VALUES ('start','package','foundation','البداية','ORIGIN','باقة تأسيس بصري للمشروعات الصغيرة: هوية، حضور اجتماعي، ومطبوعات البداية.','A visual foundation for small businesses: identity, social presence and starter print.',600000,0,0,'draft',0,'{"ar":["جلسة Brief أونلاين 30–45 دقيقة","Mini Brand Direction وMoodboard","لوجو نهائي: أساسي وأبيض وأسود وأيقونة رقمية","ألوان وخطوط مقترحة للبراند","Mini Brand Guide PDF","صورة بروفايل وCover وBio مقترح","4 بوستات إطلاق مع Captions قصيرة","Business Card أو Flyer وMenu / Price List بسيط","ملفات نهائية جاهزة للاستخدام الرقمي والطباعة"],"en":["30–45 minute online Brief","Mini Brand Direction and Moodboard","Final logo: primary, black-and-white and digital icon","Suggested brand colors and type","Mini Brand Guide PDF","Profile image, Cover and suggested Bio","4 launch posts with short Captions","Business Card or Flyer and simple Menu / Price List","Final files ready for digital and print use"]}','لا تشمل التصوير أو الفيديو أو Reels أو Landing Page أو الطباعة الفعلية أو التنقل.','Does not include photography, video, Reels, Landing Page, physical printing or transport.','12–14 يومًا','12–14 days',0,datetime('now'),datetime('now'));
INSERT OR IGNORE INTO commercial_catalog_items (id,item_type,category,name_ar,name_en,description_ar,description_en,price_minor,cost_minor,minimum_price_minor,status,visible_on_site,included_json,exclusions_ar,exclusions_en,duration_ar,duration_en,cost_reviewed,created_at,updated_at) VALUES ('presence','package','foundation','الحضور','PRESENCE','باقة تجهيز كاملة: هوية، محتوى بداية، Landing Page ومطبوعات أساسية.','A complete setup: identity, launch content, Landing Page and essential print.',1100000,0,0,'draft',0,'{"ar":["كل مكونات البداية","تجهيز Facebook وInstagram وربط WhatsApp عند توفر الصلاحية","8 تصميمات Feed و4 Story Templates","8 Captions وContent Plan لأول شهر","Landing Page عربية من صفحة واحدة حتى 6 أقسام","Business Card وFlyer وMenu / Price List بسيط","ملفات التسليم النهائية الجاهزة للاستخدام"],"en":["Everything in Origin","Facebook and Instagram setup with WhatsApp link when access is available","8 Feed designs and 4 Story Templates","8 Captions and a first-month Content Plan","One-page Arabic Landing Page up to 6 sections","Business Card, Flyer and simple Menu / Price List","Final files ready for use"]}','لا تشمل التصوير أو الفيديو أو Reels أو الطباعة الفعلية أو الشحن أو التنقل أو دومين مدفوع.','Does not include photography, video, Reels, physical printing, shipping, transport or a paid domain.','18–21 يومًا','18–21 days',0,datetime('now'),datetime('now'));
